      SUBROUTINE ELMENT(NWK)CC     EVALUATES THE NUMERICAL EFFECT OF EACH ELEMENTCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'BETAC.CIN'      INCLUDE 'COCOM.CIN'      INCLUDE 'CONSTS.CIN'      INCLUDE 'COP.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'DATA2D.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM0C.CIN'      INCLUDE 'ELM0D.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM1C.CIN'      INCLUDE 'ELM1D.CIN'      INCLUDE 'ELM2A.CIN'      INCLUDE 'ELM2B.CIN'      INCLUDE 'ELM2D.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM4D.CIN'      INCLUDE 'ELM4E.CIN'      INCLUDE 'ELM5A.CIN'      INCLUDE 'ELM5B.CIN'      INCLUDE 'ELM6.CIN'      INCLUDE 'ELM7B.CIN'      INCLUDE 'ELM8A.CIN'      INCLUDE 'ELM8B.CIN'      INCLUDE 'ELM8C.CIN'      INCLUDE 'ELM8G.CIN'      INCLUDE 'ELM8H.CIN'      INCLUDE 'ELM8L.CIN'      INCLUDE 'ELM9.CIN'      INCLUDE 'ELM10A.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM10E.CIN'      INCLUDE 'ELM13A.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM14A.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM15B.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'ELM16A.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'ELM20.CIN'      INCLUDE 'ELM23.CIN'      INCLUDE 'ELM24A.CIN'      INCLUDE 'ELM26A.CIN'      INCLUDE 'ELM26B.CIN'      INCLUDE 'ELM31A.CIN'      INCLUDE 'ELM38A.CIN'      INCLUDE 'ELM38B.CIN'      INCLUDE 'ELM39A.CIN'      INCLUDE 'ELM39C.CIN'      INCLUDE 'ELM42.CIN'      INCLUDE 'ETACOM.CIN'      INCLUDE 'ETAP.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'HORNS.CIN'      INCLUDE 'INDBND.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'LXRAN.CIN'      INCLUDE 'NHORN.CIN'      INCLUDE 'NXRAN.CIN'      INCLUDE 'R.CIN'      INCLUDE 'RCP.CIN'      INCLUDE 'R2P.CIN'      INCLUDE 'R3P.CIN'      INCLUDE 'SI.CIN'      INCLUDE 'STEPT1.CIN'      INCLUDE 'XRAN.CIN'      INCLUDE 'XRAN4.CIN'      INCLUDE 'ZHORN.CIN'CC     LOCAL VARIABLESC      EXTERNAL        DATAR, IDATACC-----------------------------------------------------------------------C           L = 0.0      TH = 0.0      CALL DEPIC2      IF (TYPE .NE. 14) THEN        IF (.NOT. RMTX .AND. .NOT. OMTX) GO TO 80        IF (.NOT. RMTX) GO TO 70      ELSE        IF (TYP1 .EQ. 14) GO TO 80      ENDIFC      DCOV = .FALSE.      DO 52 J = 1, 6   52 COD(J) = 0.0      IF (NORD1 .GE. 1) THEN        DO 55 J = 1, 36   55   RL(J) = 0.0        DO 60 J = 1, 36, 7   60   RL(J) = 1.0      ENDIFC   70 IF (ALIGN .AND. RMTX) THEN        CALL PICKUP(1)        IF (.NOT. RCP .AND. .NOT. R2P .AND. .NOT. R3P) CALL PICKUP(2)        IF (.NOT. R2P .AND. .NOT. R3P) CALL PICKUP(3)        IF (TYPE .EQ. 3 .OR. TYPE .EQ. 4 .OR. TYPE .EQ. 5     1      .OR. TYPE .EQ. 11 .OR. TYPE .EQ. 18 .OR. TYPE .EQ. 19     2      .OR. TYPE .EQ. 28 .OR. TYPE .EQ. 29)     3      LAST = LABEL(NUM)(1:8)      ENDIFC   80 NWK = 0      IF (.NOT. RANZC) GO TO 90      IF (.NOT. LXRAN) GO TO 90C      INDEX = TYPE      IF (TYPEC .EQ. 8) INDEX = TYPEC      NXR = NXRAN(INDEX)      IF (NXR .GT. 0) THEN        DO 85 J = 1, NXR        XRAN(J) = RANDIS()   85   CONTINUE         ENDIFC      IF (TYPE .EQ. 2 .AND. BEFORE) THEN        NXR = NXRAN(2)        DO 86 J = 1, NXR   86   XRAN2I(J) = XRAN(J)        NXR = NXRAN(4)        DO 87 J = 1, NXR        XRAN(J) = RANDIS()   87   XRAN4(J) = XRAN(J)      ENDIFC      LXRAN = .FALSE.C   90 IF (TYPE .GE. 82 .AND. TYPE .LE. 86) GO TO 7800      GO TO ( 100, 200, 300, 400, 500, 600, 700, 800, 900,1000,     1       1100,1200,1300,1400,1500,1600,1700,1800,1900,2000,     2       2100,2200,2300,2400,2500,2600,2700,2800,2800,3000,     3       3100,3200,3300,3400,3500,3500,3700,3800,3900,4000,     4       4100,4200,4300,5020,4500,4600,4600,4600), TYPECC     1. -- BEAMC  100 CALL BEAMIN      GO TO 5020CC     2. -- POLE FACE ROTATIONC  200 IF (TYPEC .EQ. 20) GO TO 250      IF (TYPEC .EQ. 8) GO TO 260C      IF (BEFORE .AND. .NOT. DMC) THEN        IBEND = ISTOR(NUM4)        CALL BGET(IBEND)        CALL SKETCH(NUM)      ENDIF      CALL BFGET      IF (NORD1 .GE. 3 .AND. (LAYL .EQ. 0.0 .OR. APB(2) .EQ. 0.0)) THEN        WRITE (NOUT,9016) 9016   FORMAT (' *** ERROR *** FRINGING FIELD MUST HAVE NONZERO',     1          ' EXTENT IN THIRD ORDER')        FLUSHL = .TRUE.        GO TO 5020      ENDIF      CALL FRINGE      GO TO 5000C  250 WRITE (NOUT,9005)      FLUSHL = .TRUE.      GO TO 5020C  260 NMIS = NM4      NMISE = NUM4      NUPD = 3      CALL MISGET      IF (VMMAX .NE. 0 .OR. NV3 .NE. 0) THEN        CALL MALIGN        IF (FLUSHL) GO TO 5020        IF (LFM .GE. 1 .AND. LTAB .EQ. 0) GO TO 5000      ENDIF      GO TO 5020CC     3. -- DRIFT SPACEC  300 IADR = I + 1      L = DATAR(IADR)      IF (PRAN3 .NE. 0.0) L = L + PRAN3*XRAN(1)      L = L*UNITI(8)      IF (NORD1 .GE. 1) THEN        R(1,2) = L        R(3,4) = L        IF (SM .NE. 0.0 .AND. RI .NE. 0.0) R(5,6) = L/GAMMA**2       ENDIF      IT = IPTOJ(2)      IF (IT .EQ. 0) THEN        NUMTYP = IT      ELSE        NUMTYP = IDATA(I + IT)      ENDIF      GO TO 5000CC     4. -- BENDING MAGNETC  400 IF (TYPEC .EQ. 8) GO TO 460      IF (TYPEC .EQ. 20) GO TO 450      IF (.NOT. FFIN) CALL BGET(I)      L = LBEND      LMAG = L      TOTANG = TOTANG + ALC      CALL BVGET      CALL BEND      IF (FLUSHL) GO TO 5020      GO TO 5000C  450 WRITE (NOUT,9005) 9005 FORMAT (' TILT NOT PERMITTED ON BEND -- TRY RBEND OR SBEND')      FLUSHL = .TRUE.      GO TO 5020C  460 NMIS = NM4      NUPD = 1      IF (FFIN .OR. FFOUT) NUPD = 3      CALL MISGET      IF (VMMAX .NE. 0.0 .OR. NV3 .NE. 0) THEN        NMISE = NUM        NUM4 = NUM        CALL MALIGN        IF (FLUSHL) GO TO 5020        IF (LFM .GE. 1 .AND. LTAB .EQ. 0) GO TO 5000      ENDIF      GO TO 5020 CC     5. -- QUADRUPOLEC  500 IF (TYPEC .EQ. 20) GO TO 560      IF (TYPEC .EQ. 8) GO TO 570C      CALL GGET      IF (NORD1 .LT. 1) GO TO 550C      KX2 = KQ2      JQUAD = 1      CALL FOCUS      CX = R(1,1)      SX = R(1,2)      JQUAD = 3      KQ2 = - KQ2      KY2 = KQ2      CALL FOCUS      CY = R(3,3)      SY = R(3,4)      IF (SM .NE. 0.0 .AND. RI .NE. 0.0) R(5,6) = L/GAMMA**2 C  550 GO TO 5000C  560 IROLL = IPTOJ(6)      IF (IROLL .EQ. 0) GO TO 5020      IADR = I + IROLL      TH = DATAR(IADR)*UNITI(13)      IF (.NOT. BEFORE) TH = - TH      CALL ROTATE(NPM)      IF (NPM .EQ. 4) GO TO 2040      IF (.NOT. REFER) GO TO 5000      GO TO 5020C  570 NMIS = NM5      NUPD = 1      CALL MISGET      IF (VMMAX .NE. 0.0 .OR. NV3 .NE. 0) THEN        NMISE = NUM        CALL MALIGN        IF (FLUSHL) GO TO 5020        IF (LFM .GE. 1 .AND. LTAB .EQ. 0) GO TO 5000      ENDIF      GO TO 5020CC     6. -- UPDATEC  600 IF (.NOT. ATWE) GO TO 5020      IF (TYPEC .EQ. 8) GO TO 650      JA = INT(DATA(I+1))      KA = INT(DATA(I+2))      IF (JA .NE. 0) GO TO 5020      IF (NORD3 .GT. 1 .AND. .NOT. NOPH .AND. R2P) THEN        WRITE (NOUT,9003) 9003   FORMAT (' *** ERROR *** UPDATE NOT PERMITTED WITH OFF-AXIS',     1          ' EXPANSION, NONZERO PHASE SPACE, AND SECOND-ORDER',     2          ' MATRIX DISPLAY')        FLUSHL = .TRUE.        GO TO 5020      ENDIF      IF (KA .EQ. 1) THEN        IF (RCP .OR. R2P .OR. R3P) CALL UPDATE      ELSE IF (KA .EQ. 2) THEN        IF (R2P .OR. R3P) CALL UPDAT2      ENDIF      GO TO 5020C  650 IF (JA .NE. 0) GO TO 5020      BEFORE = .TRUE.      CALL MISGET      IF (VMMAX .NE. 0.0 .OR. NV3 .NE. 0) THEN        IF (LTAB .EQ. 1) THEN          IF (NM .GE. 10) GO TO 5020          LABM(NM+1) = LAST(1:8)        ENDIF        CALL MALIGN        IF (FLUSHL) GO TO 5020        IF (LFM .GE. 1 .AND. LTAB .EQ. 0) GO TO 5000      ENDIF      GO TO 5020CC     7. -- BEAM CENTROID SHIFTC  700 DO 710 J = 1, 6      IPLUSJ = I + J      COD(J) = DATAR(IPLUSJ)      IF (PRAN7(J) .NE. 0.0)     1    COD(J) = COD(J) + PRAN7(J)*XRAN(J)      COD(J) = COD(J)*UNITI(J)  710 CONTINUE      RECENT = .FALSE.      DCOV = .TRUE.C      IF (SOFA) THEN        DO 712 J = 1, 6  712   CO(J) = CO(J) + COD(J)      ELSE        DO 716 J = 1, 6  716   CO(J) = COD(J)        SOFA = .TRUE.        NORD1 = NORDX        IF (BAX) THEN          DO 720 J = 1, 6  720     COF(J) = CO(J)          R1P = .TRUE.        ENDIF      ENDIF      GO TO 5020CC     8. -- MAGNET MISALIGNMENTC  800 IF (.NOT. ATWE) GO TO 5020      IF (ACCEL) GO TO 890      VMMAX = 0.0      DO 810 J = 1, 6      IPLUSJ = I + J      I2MOD = 2 - MOD(J,2)      VM(J) = DATAR(IPLUSJ)*UMIS(I2MOD)      VMMAX = AMAX1(VMMAX,ABS(VM(J)))  810 CONTINUEC      TYT  = INT(DATA(I+7))      RORC = MOD(TYT,10)      LTAB = MOD(TYT/10,10)      LFM = TYT/100      IR = RORC + 1      IF (VMMAX .EQ. 0.0 .AND. NV3 .EQ. 0) THEN        TYT = 0        GO TO 5020      ENDIFC      IF (IPTOJ(8) .EQ. 0) THEN        MCF = MCFO      ELSE        MCF = INT(DATA(I+8))      ENDIF      TMK = MCF/100      CHORD = MOD(MCF/10,10) .EQ. 0      FEO = MOD(MCF,10) .EQ. 1C      IF (RORC .GE. 3) GO TO 850      IF (LFM .EQ. 2) THEN        DO 820 J = 1, 6        VM(J) = VMSAV(IR,IVMS(IR),J)  820   CONTINUE        IVMS(IR) = IVMS(IR) - 1      ENDIFC      IF (LTAB .EQ. 1) THEN        IF (NM .GE. 10) GO TO 5020        LABM(NM+1) = LAST(1:8)      ENDIF      BEFORE = .FALSE.      NMIS = NUM      IF (LFM .EQ. 0 .AND. (R2P .OR. R3P)) CALL UPDAT2      CALL MALIGN      IF (FLUSHL) GO TO 5020      IF (LFM .GE. 1 .AND. LTAB .EQ. 0) GO TO 5000      GO TO 5020C  850 IF (RORC .EQ. 3 .OR. RORC .EQ. 4) THEN        ALO(1) = .TRUE.        NM4 = NUM      ENDIF      IF (RORC .EQ. 3 .OR. RORC .EQ. 5) THEN        ALO(2) = .TRUE.        NM5 = NUM      ENDIF      GO TO 5020C  890 WRITE (NOUT,9002) 9002 FORMAT (' *** ERROR *** MISALIGNMENTS NOT PERMITTED WITH',     1        ' ACCELERATOR NOTATION')      FLUSHL = .TRUE.      GO TO 5020CC     9. -- REPEATC  900 NREP = IDATA(I+1)      CALL REPEAT1      GO TO 5020CC     10. -- FITTING CONSTRAINTSC 1000 DRC = .FALSE.      JCON = IDATA(I+1)      KCON = IDATA(I+2)      DE0 = DATAR(I+3)      SD = DATAR(I+4)      IF (SD .EQ. 0.0) THEN        WRITE (NOUT,9805) 9805   FORMAT (' *** ERROR *** TOLERANCE OF ZERO ON FIT ELEMENT ',     1          'NOT ACCEPTABLE')        FLUSHL = .TRUE.        GO TO 5020      ENDIF      CTY = TIE(I+1)      NC = NC + 1      CALL CONSTR      IF (FLUSHL) GO TO 5020      IF (LSTEPN) THEN        ID1 = IPTOJ(10)        ID2 = IPTOJ(11)        DATA(I+ID1) = DATA(I+ID1) + COC        DATA(I+ID2) = DATA(I+ID2) + COC**2      ENDIF      GO TO 5020CC     11. -- ACCELERATORC 1100 CALL ACCGET      CALL ACCMTX      GO TO 5000CC     12. -- CORRELATIONS IN BEAM ELLIPSEC 1200 IF (NORD3 .LT. 1) GO TO 5020      N  =  0      DO 1210 J = 2, 6      JMIN1 = J - 1      DO 1210 K = 1, JMIN1      N = N + 1      IPLUSN = I + N      SI(K,J) = DATAR(IPLUSN)*SQRT(SI(J,J)*SI(K,K))      SI(J,K) = SI(K,J) 1210 CONTINUE      GO TO 5020CC     13. -- INPUT-OUTPUT OPTIONSC 1300 CDB = INT(DATA(I+1))      IF (CDB .EQ. 9 .AND. .NOT. R1P) GO TO 1310C 1310 IF (ATWE) THEN        CALL IDIOT      ELSE        OMTX = .FALSE.        CFIT = .FALSE.      ENDIF      IF (CDB .EQ. 11) GO TO 5000      GO TO 5020CC     14. -- ARBITRARY MATRIXC 1400 J1 = INT(DATA(I+7))      IF (J1 .LE. 0 .OR. J1 .GT. 6) THEN        WRITE (NOUT,9013) J1 9013   FORMAT (' *** ERROR *** ILLEGAL MATRIX INDEX, J1 = ',I5)        FLUSHL = .TRUE.        GO TO 5020      ENDIF      DO 1410 K = 1, 6      IPLUSK = I + K      R(J1,K) = DATA(IPLUSK)*UNITI(J1)/UNITI(K) 1410 CONTINUE      IF (NDIF .EQ. 1 .AND. NUM + 1 .GT. NEL) GO TO 5000      IF (NDIF .EQ. -1 .AND. NUM - 1 .LE. 0) GO TO 5000      IPNOTY = ISTOR(NUM + NDIF)      NEXT = IDATA(IPNOTY)      I14S = NEXT      I14T = NEXT      IF (NEXT .EQ. TYPE) GO TO 5005      GO TO 5000CC     15. -- UNITSC 1500 J = INT(DATA(I+1))      IF (J .EQ. 20) GO TO 1510      XNAME = LABEL(NUM)(1:4)      USIZE = DATA(I+2)      CALL UNITS(J)      GO TO 5020C 1510 MPMAD = .TRUE.      GO TO 5020CC     16. -- SPECIAL PARAMETERSC 1600 NPARS = INT(DATA(I+1))      IADR = I + 2      PARAM = DATAR(IADR)      IF (NPARS .LE. 0 .OR. (NPARS .GT. 27 .AND. NPARS .LT. 100)     1    .OR. (NPARS .GT. 110 .AND. NPARS .LT. 200)     2    .OR. (NPARS .GT. 202 .AND. NPARS .LT. 250)     3    .OR. NPARS .GT. 254) GO TO 1699      IF (NPARS .GT. 27) GO TO 5020      CALL SPESHL      GO TO 5020C 1699 WRITE (NOUT,3390) 3390 FORMAT ('0  ERROR - CHECK INPUT DATA FOR SPECIAL PARAMETER')      GO TO 5020CC     17. -- SECOND- OR THIRD-ORDER CALCULATIONC 1700 IF (RCP .OR. R2P .OR. RCP) THEN        WRITE (NOUT,9004) 9004   FORMAT (' *** ERROR *** ORDER ELEMENT MUST PRECEDE ANY ',     1          'ELEMENT WHICH HAS A TRANSFER MATRIX')        FLUSHL = .TRUE.        GO TO 5020      ENDIF      NORDX = INT(DATA(I+1))      NORDY = INT(DATA(I+2))      IF (ACCEL .OR. LTWISS) NORDY = 1      NORDX = MAX0(NORDX,NORDY)      NORD1 = NORDY      NORD3 = NORDY      NORD2 = NORD3      IF (ALIGN .OR. SOFA .OR. ACCEL) NORD1 = NORDX      IF (ALIGN) NORD2 = NORD1      IF (.NOT. LIMTD) LINEAR = .TRUE.      CALL ORDCK      GO TO 5020CC     18. -- SEXTUPOLEC 1800 IF (TYPEC .EQ. 20) GO TO 1860      IF (TYPEC .EQ. 8) GO TO 1870      IF (RORC .EQ. 3 .OR. RORC .EQ. 6) THEN        IF (NM .GE. 10) GO TO 1801        LABM(NM+1) = LABEL(NUM)(1:8)        DMC = .TRUE.      ENDIFC 1801 CALL SEXGETC 1840 IF (NORD1 .GE. 1) THEN        R(1,2) = L        R(3,4) = L        IF (SM .NE. 0.0 .AND. RI .NE. 0.0) R(5,6) = L/GAMMA**2       ENDIF      GO TO 5000C 1860 IROLL = IPTOJ(5)      IADR = I + IROLL      TH = DATAR(IADR)*UNITI(13)      IF (.NOT. BEFORE) TH = - TH      CALL ROTATE(NPM)      IF (NPM .EQ. 4) GO TO 2040      IF (.NOT. REFER) GO TO 5000      GO TO 5020C 1870 GO TO 5020CC     19. -- SOLENOIDC 1900 IF (ACCEL .OR. LTWISS) GO TO 2040      CALL SOLGET      IF (NORD1 .GE. 1) CALL SOLEN      GO TO 5000CC     20. -- BEAM ROTATIONC 2000 IADR = I + 1      TH = DATAR(IADR)      IF (PRAN20 .NE. 0.0) TH = TH + PRAN20*XRAN(1)      TH = TH*UNITI(13)      IT = IPTOJ(2)      IF (IT .EQ. 0) THEN        NUMTYP = IT      ELSE        NUMTYP = IDATA(I + IT)      ENDIF      CALL ROTATE(NPM)      IF (NPM .EQ. 4) GO TO 2040      IF (.NOT. REFER) GO TO 5000      GO TO 5020C 2040 WRITE (NOUT,2098) 2098 FORMAT (' *** ERROR *** ROTATION INCOMPATABLE WITH ACCELERATOR',     1        ' NOTATION')      FLUSHL = .TRUE.      GO TO 5020CC     21. -- STRAY FIELDC 2100 DO 2105 JK = 1, 36 2105 RL(JK) = 0.0      DO 2110 JK = 1, 36, 7 2110 RL(JK) = 1.0      DO 2120 J = 1, 6      VM(J) = 0.0 2120 CONTINUE      J = INT(DATA(I+1))      IF (J .LE. 0 .OR. J .GT. 6) THEN        WRITE (NOUT,9014) J 9014   FORMAT (' *** ERROR *** ILLEGAL MISALIGNMENT INDEX = ',I5)        FLUSHL = .TRUE.        GO TO 5020      ENDIF      IF (DATA(I+3) .EQ. 0.0) THEN        TYT = 110        VM(J) = DATA(I+2)      ELSE        TYT = 0        VM(J) = DATA(I+3)      ENDIF      LFM = TYT/100      LTAB = MOD(TYT/10,10)      VM(J) = VM(J)*UNITI(9)*UNITI(8)/RI      IF (R2P .OR. R3P) CALL UPDAT2      CALL MALIGN      IF (FLUSHL) GO TO 5020      IF (LFM .GE. 1 .AND. LTAB .EQ. 0) GO TO 5000      GO TO 5020CC     22. -- DEFINE REGISTER CONTENTSC 2200 IF (.NOT. DRC) THEN        CALL FIND10        IF (TYPE .LT. 0) GO TO 5100        IF (.NOT. DRC) GO TO 5020      ENDIF      JCON = IDATA(I+1)      IF (JCON .NE. 100) THEN        KCON = IDATA(I+2)        JTIE = TIE(I+3)        IF (JTIE .NE. 100) THEN          JREG = IDATA(I+3)        ELSE          JREG = IDATA(I+3)        ENDIF      ELSE        ACON = DATA(I+3)      ENDIF      DE0 = 0.0      SD = 1.0      CALL CONSTR      GO TO 5020CC     23. -- ALGEBRAIC OPERATIONSC 2300 K1REG = IDATA(I+1)      K1TIE = TIE(I+1)      K2REG = IDATA(I+2)      K2TIE = TIE(I+2)      IOPN = IDATA(I+3)      JREG = IDATA(I+4)      JTIE = TIE(I+4)      CALL COMBIN      GO TO 5020CC     24. -- DEFINE SECTIONC 2400 JDEF = IDATA(I+1)      IF (JDEF .EQ. 3 .OR. JDEF .EQ. 4) THEN        NADDEF(1) = IDATA(I+2)        NADDEF(2) = IDATA(I+3)      ENDIF      CALL DEFINE      GO TO 5020CC     25. -- OCTUPOLEC 2500 IF (TYPEC .EQ. 20) GO TO 2550C      CALL OCTGET      IF (NORD1 .GE. 1) THEN        R(1,2) = L        R(3,4) = L        IF (SM .NE. 0.0 .AND. RI .NE. 0.0) R(5,6) = L/GAMMA**2      ENDIF      GO TO 5000C 2550 IROLL = IPTOJ(5)      IADR = I + IROLL      TH = DATAR(IADR)*UNITI(13)      IF (.NOT. BEFORE) TH = - TH      CALL ROTATE(NPM)      IF (NPM .EQ. 4) GO TO 2040      IF (.NOT. REFER) GO TO 5000      GO TO 5020CC     26. -- RANDOM CHANGE OF PHYSICAL PARAMETERC 2600 CALL ERRSET      GO TO 5020CC     27. -- ACCELERATOR ETA FUNCTIONC 2700 RAY = .TRUE.      NORD1 = NORDX      DO 2710 J = 1, 6      IPLUSJ = I + J      ETA(J) = DATA(IPLUSJ)*UBEAM(J) 2710 CONTINUE      GO TO 5020CC     28. -- RECTANGULAR BENDING MAGNETC                  ORC     29. -- SECTOR BENDING MAGNETC 2800 IF (TYPEC .EQ. 4) GO TO 2840      IF (TYPEC .EQ. 20) GO TO 2850      IF (TYPEC .EQ. 8) GO TO 2860      IF ((RORC .EQ. 3 .OR. RORC .EQ. 4) .AND. NM .LT. 10) THEN        IF (BEFORE) CALL PICKUP(3)        IF (.NOT. BEFORE) LABM(NM+1) = LABEL(NUM)(1:8)        DMC = .NOT. BEFORE      ENDIFC      IF (BEFORE) CALL RBGET      CALL RBFGET      IF (NORD1 .GE. 3 .AND. (LAYL .EQ. 0.0 .OR. APB(2) .EQ. 0.0)) THEN        WRITE (NOUT,9016)        FLUSHL = .TRUE.        GO TO 5020      ENDIF      CALL FRINGE      GO TO 5000C 2840 L = LBEND      LMAG = L      CALL RBVGET      TOTANG = TOTANG + AL      CALL BEND      IF (FLUSHL) GO TO 5020      GO TO 5000C 2850 NROLL = 24      IROLL = IPTOJ(NROLL)      IADR = I + IROLL      TH = DATAR(IADR)*UNITI(13)      IF (.NOT. BEFORE) TH = - TH      CALL ROTATE(NPM)      IF (NPM .EQ. 4) GO TO 2040      IF (.NOT. REFER) GO TO 5000      GO TO 5020C 2860 IF (.NOT. DMC) GO TO 5020      NMIS = NM4      NUPD = 3      CALL MISGET      IF (VMMAX .NE. 0.0 .OR. NV3 .NE. 0) THEN        NMISE = NUM        NUM4 = NUM        CALL MALIGN        IF (FLUSHL) GO TO 5020        IF (LFM .GE. 1 .AND. LTAB .EQ. 0) GO TO 5000      ENDIF      GO TO 5020CC     30. -- PARAMETERC 3000 IADR = I + 1      PARAM = DATAR(IADR)      GO TO 5020CC     31. -- POSITION MARKERC 3100 IF (.NOT. MKG) THEN        NMARKS = IDATA(I+1)        CALL AGENDA(1)        ATWE = PMK        DRC = .FALSE.      ENDIF      GO TO 5020CC     32. -- DUMMY ARGUMENTC 3200 JDEF = IDATA(I+1)      NADDEF(1) = IDATA(I+2)      CALL ARGUE      GO TO 5020CC     33. -- STORAGE OF MATRIX ELEMENTC 3300 DRC = .FALSE.      IF (.NOT. ATWE) GO TO 5020      IADR = IDATA(I+1)      PARAM = DATA(IADR)      GO TO 5020CC     34. -- PLASMA LENSC 3400 CALL PLSGET      IF (NORD1 .GE. 1) THEN        KX2 = KQ2        JQUAD = 1        CALL FOCUS        CX = R(1,1)        SX = R(1,2)        JQUAD = 3        KY2 = KQ2        CALL FOCUS        CY = R(3,3)        SY = R(3,4)        IF (SM .NE. 0.0 .AND. RI .NE. 0.0) R(5,6) = L/GAMMA**2       ENDIF      GO TO 5000CC     35. -- HKICK -- HORIZONTAL VERNIERC                     ORC     36. -- VKICK -- VERTICAL VERNIERC 3500 NROT35 = 5      IF (TYPEC .EQ. 35) GO TO 3540      IF (TYPEC .EQ. 20) GO TO 3550      CALL VRBGET      BE = 0.0      RABT = 0.0      APB(2) = APBI(2)      LAYK = 0.0      LAYL = 0.5      LAYX = 0.0      IF (NORD1 .GE. 3 .AND. (LAYL .EQ. 0.0 .OR. APB(2) .EQ. 0.0)) THEN        WRITE (NOUT,9016)        FLUSHL = .TRUE.        GO TO 5020      ENDIF      CALL FRINGE      GO TO 5000C 3540 L = LBEND      CALL VERN      IF (AL .NE. 0.0) THEN        DCOV = .TRUE.        IF (BAX) R1P = .TRUE.      ENDIF      GO TO 5000C 3550 IROLL = IPTOJ(NROT35)      IF (IROLL .EQ. 0) THEN        TH = 0.0      ELSE        IADR = I + IROLL        TH = DATAR(IADR)*UNITI(13)      ENDIF      IF (TYPE .EQ. 36) TH = TH + 0.5*PI      IF (.NOT. BEFORE) TH = - TH      CALL ROTATE(NPM)      IF (NPM .EQ. 4) GO TO 2040      IF (.NOT. REFER) GO TO 5000      GO TO 5020CC     37. -- ALIGNMENT MARKERC 3700 IF (TYPEC .EQ. 8) GO TO 3750      JA = INT(DATA(I+1))      KA = INT(DATA(I+2))      IF (JA .NE. 0) GO TO 5020C      IADR = I + IPTOJ(4)      NUPS = IDATA(IADR)      NKNOW = 0      NUNC = 0      IF (NUPS .NE. 0) THEN        DO 3710 NAL = 1, NUPS        NMIS = IDATA(IADR+NAL)        IMIS = ISTOR(NMIS)        ICODE = INT(DATA(IMIS+7))        LFM = ICODE/100        IF (LFM .EQ. 0) NUNC = NUNC + 1        IF (LFM .GE. 1) NKNOW = NKNOW + 1 3710   CONTINUE      ENDIFC      IF (NKNOW .GE. 1 .AND. NORD3 .GE. 2 .AND. .NOT. NOPH     1    .AND. R2P) THEN        WRITE (NOUT,9003)        FLUSHL = .TRUE.        GO TO 5020      ENDIFC      IF (KA .EQ. 1) THEN        IF (RCP .OR. R2P .OR. R3P) THEN          IF (NUNC .EQ. 0 .AND. NKNOW .GT. 0) CALL RESET(2)          IF (NUNC .GT. 0) CALL UPDATE        ENDIF      ELSE IF (KA .EQ. 2) THEN        IF (R2P .OR. R3P) THEN          IF (NUNC .EQ. 0 .AND. NKNOW .GT. 0) CALL RESET(3)          IF (NUNC .GT. 0) CALL UPDAT2        ENDIF      ENDIF      GO TO 5020C 3750 IF (JA .NE. 0) GO TO 5020      BEFORE = .TRUE.      CALL MISGET      IF (VMMAX .NE. 0.0 .OR. NV3 .NE. 0) THEN        IF (LTAB .EQ. 1) THEN          IF (NM .GE. 10) GO TO 5020          LABM(NM+1) = LAST(1:8)        ENDIF        CALL MALIGN        IF (FLUSHL) GO TO 5020        IF (LFM .GE. 1 .AND. LTAB .EQ. 0) GO TO 5000      ENDIF      GO TO 5020CC     PLOT -- PLOT OF MATRIX ELEMENTSC 3800 PLOT = .TRUE.      NPLT = NPARMS/2      IDIF = 1      IF (.NOT. LPLOT) THEN        DO 3810 J = 1, NPLT        JPLOT(J) = IDATA(I+IDIF)        KPLOT(J) = IDATA(I+IDIF+1)        IDIF = IDIF + 2        JCON = JPLOT(J)        KCON = KPLOT(J)        EPLOT(J) = JCON .EQ. KCON .AND. JCON .GE. 1 .AND. JCON .LE. 6        IF (.NOT. PLNOW .AND. .NOT. LPLOT) THEN          IF (JCON .EQ. 0 .AND. KCON .EQ. 0) LPLOT = .TRUE.          IF (JCON .EQ. 8) LPLOT = .TRUE.        ENDIF 3810   CONTINUE      ENDIFC      IF (.NOT. LPLOT) PLNOW = .TRUE.      GO TO 5020CC     LIMIT -- SET LIMITS ON VARIED QUANTITIESC 3900 TYPEL = INT(DATA(I+1))      NPARL = INT(DATA(I+2))      LTYPE = INT(DATA(I+3))      DPARL = DATA(I+4)      IF (LTYPE .EQ. 1 .OR. LTYPE .EQ. 2) THEN        CALL LIMSET      ELSE IF (LTYPE .EQ. 3) THEN        LTYPE = 1        DPARL = - ABS(DPARL)        CALL LIMSET        LTYPE = 2        DPARL = ABS(DPARL)        CALL LIMSET      ENDIF      LIMTD = .TRUE.      LINEAR = .FALSE.      GO TO 5020CC     DESCRIPTIONS OF MAGNETS BY TYPEC 4000 GO TO 5020CC     ELECTROSTATIC SEPTUMC 4100 IF (TYPEC .EQ. 20) GO TO 4160      CALL SEPTUM      GO TO 5000C 4160 IROLL = IPTOJ(NTILT)      IF (IROLL .EQ. 0) GO TO 5020      IADR = I + IROLL      TH = DATAR(IADR)*UNITI(13)      IF (.NOT. BEFORE) TH = - TH      CALL ROTATE(NPM)      IF (NPM .EQ. 4) GO TO 2040      IF (.NOT. REFER) GO TO 5000      GO TO 5020CC     42. -- KICKER -- CORRECTOR FOR BOTH PLANESC 4200 LBEND = DATAR(I+1)*UNITI(8)      HAL = - DATAR(I+2)*UNITI(7)      VAL = - DATAR(I+3)*UNITI(7)      AL = SQRT(HAL**2 + VAL**2)      AL = SIGN(AL,HAL)      H0 = AL/LBENDC      IF (TYPEC .EQ. 20) GO TO 4240      IF (TYPEC .EQ. 2) GO TO 4220C      L = LBEND      B = RI*H0      CALL VERN      IF (AL .NE. 0.0) THEN        DCOV = .TRUE.        IF (BAX) R1P = .TRUE.      ENDIF      GO TO 5000C 4220 BE = 0.0      RABT = 0.0      APB(2) = APBI(2)      LAYK = 0.0      LAYL = 0.5      LAYX = 0.0      IF (NORD1 .GE. 3 .AND. (LAYL .EQ. 0.0 .OR. APB(2) .EQ. 0.0)) THEN        WRITE (NOUT,9016)        FLUSHL = .TRUE.        GO TO 5020      ENDIF      CALL FRINGE      GO TO 5000C 4240 HAL = - DATAR(I+2)*UNITI(7)      VAL = - DATAR(I+3)*UNITI(7)      AL = SQRT(HAL**2 + VAL**2)      AL = SIGN(AL,HAL)      IF (HAL .NE. 0) THEN        TH = ATAN(VAL/HAL)      ELSE        IF (VAL .GT. 0) THEN          TH = 0.5*PI        ELSE IF (VAL .LT. 0) THEN          TH = - 0.5*PI        ELSE          TH = 0.0        ENDIF      ENDIF      IF (.NOT. BEFORE) TH = - TH      CALL ROTATE(NPM)      IF (NPM .EQ. 4) GO TO 2040      IF (.NOT. REFER) GO TO 5000      GO TO 5020CC     43. -- REFERENCE COORDINATE SYSTEM SHIFTC 4300 DO 4310 J = 1, 6      IPLUSJ = I + J      COD(J) = DATA(IPLUSJ)      IF (PRAN43(J) .NE. 0.0)     1    COD(J) = COD(J) + PRAN43(J)*XRAN(J)      COD(J) = COD(J)*UNITI(J) 4310 CONTINUE      RECENT = .FALSE.      DCOV = .TRUE.C      IF (SOFA) THEN        DO 4312 J = 1, 6 4312   CO(J) = CO(J) + COD(J)      ELSE        DO 4316 J = 1, 6 4316   CO(J) = COD(J)        SOFA = .TRUE.        NORD1 = NORDX        IF (BAX) THEN          DO 4320 J = 1, 6 4320     COF(J) = CO(J)          R1P = .TRUE.        ENDIF      ENDIFC      IF (.NOT. (ALIGN .OR. LAY)) GO TO 5020      IF (.NOT. (RCP .OR. R2P)) GO TO 5020      CALL OSET      GO TO 5020CC     45. -- NEUTRINO HORNC 4500 NHORN = NHORN + 1      N = NHORN      L = ZHORN(N,LASTH(N)) - ZHORN(N,1)      GO TO 5020CC     46. -- HMONITORC         ORC     47. -- VMONITORC         ORC     48. -- MONITORC 4600 IADR = I + 1      L = DATAR(IADR)      L = L*UNITI(8)      IF (NORD1 .GE. 1) THEN        R(1,2) = L        R(3,4) = L        IF (SM .NE. 0.0 .AND. RI .NE. 0.0) R(5,6) = L/GAMMA**2       ENDIF      GO TO 5000CC     DEFAULT UNITS SETC 7800 CALL UNITS(TYPE)      GO TO 5020CC     INDICATE WHETHER ELEMENT HAS MATRIXC 5000 NWK = 1      RECENT = .FALSE.      IF (ALIGN .OR. LAY) CALL OSET      IF (TYPE .NE. 8 .AND. TYPEC .NE. 8) CALL OSAVE 5005 IF (NORD1 .GE. 2) CALL SECORD      IF (TYPE .EQ. 14 .AND. NEXT .EQ. TYPE) GO TO 5010      IF (REFER .AND. TOTROT .NE. 0.0 .AND. .NOT. RSYM) THEN        IF (DCOV .OR. NORD1 .GE. 1) CALL ROTAT1(0)        IF (ALIGN .OR. LAY) CALL ROTATC(0)      ENDIF 5010 TYP1 = TYPE      LC = LC + L      GO TO 5100C 5020 NWK = 2 5100 RETURN      END